        load = 0;
        @(posedge clk);
        #1;
        if (tc !== 1'b1) begin
            $display("ERROR: counter did not reach 0 and assert tc. Got tc = %b", tc);
            errors = errors + 1;
        end

        // Test 3: Ensure counter stays at 0 when load = 0 and already 0 (saturation/stop counting)
        @(posedge clk);
        #1;
        if (tc !== 1'b1) begin
            $display("ERROR: counter did not stay at 0 (tc should remain 1). Got tc = %b", tc);
            errors = errors + 1;
        end

