        load = 1;
        data = 10'd3;
        @(posedge clk);
        #1;
        if (tc !== 1'b0) begin
            $display("ERROR: loading 3 should clear tc. Got tc = %b", tc);
            errors = errors + 1;
        end

        // Count down 1 -> count = 2
        load = 0;
        @(posedge clk);
        #1;
        if (tc !== 1'b0) begin
            $display("ERROR: count 2 should not assert tc.");
            errors = errors + 1;
        end

        // Interrupt counting by loading 1 in the middle of countdown (re-load before 0)
        load = 1;
        data = 10'd1;
        @(posedge clk);
        #1;

        // Now count is 1, decrement it
        load = 0;
        @(posedge clk);
        #1;
        if (tc !== 1'b1) begin
            $display("ERROR: reloaded timer failed to reach 0. Got tc = %b", tc);
            errors = errors + 1;
        end

        // Test 5: Maximum boundary value (10'd1023)
        load = 1;
        data = 10'h3FF;
        @(posedge clk);
        #1;
        if (tc !== 1'b0) begin
            $display("ERROR: max load should clear tc.");
            errors = errors + 1;
        end

        // Final result reporting
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
